function alertDays(t){const e=String(t||"").split(":")[2];return/^\d{4}-\d{2}-\d{2}$/.test(e)?Math.ceil((new Date(e)-new Date(today()))/864e5):null}async function viewAlerts(t){const e=await api("/notifications");NOTIF=e;const s="Notification"in window?Notification.permission:"unsupported",a=browserNotifOn(),n="serviceWorker"in navigator&&"PushManager"in window;t.innerHTML=`<div class="pagehead"><div><h1>Alerts</h1>\n    <p>Generated automatically when a bill or deadline gets within 30, 14, 7 or 1 days — or goes overdue. Shared by the whole family; hiding one only affects you.</p></div>\n    ${e.items.some(t=>!t.read)?'<button class="btn ghost small" id="readall">Mark all as read</button>':""}</div>\n    ${n?'<div class="card">\n      <h3 style="margin:0">Notifications on this device</h3>\n      <p class="muted" style="margin:4px 0 12px">Get alerts (RCA, ITP, acte, birthdays…) as push notifications on this phone/computer even when the site is closed. Tip: on a phone, first use "Add to Home Screen" to install the app.</p>\n      <div class="row"><button class="btn small" id="pushbtn">…</button><button class="btn ghost small" id="pushtest" hidden>Send a test</button></div>\n    </div>':`<div class="card">\n      <div class="row" style="justify-content:space-between">\n        <div><h3 style="margin:0">Browser notifications</h3>\n        <p class="muted" style="margin:4px 0 0">While Family Hub is open in a tab, new alerts also pop up as system notifications.</p></div>\n        ${"unsupported"===s?'<span class="muted">Not supported by this browser</span>':"denied"===s?'<span class="muted">Blocked in browser settings</span>':`<button class="btn ${a?"ghost":""} small" id="togglenotif">${a?"Turn off":"Turn on"}</button>`}\n      </div></div>`}\n    <div class="card" style="margin-top:16px">\n      ${e.items.length?`<table class="alerts"><tbody>${e.items.map(t=>{const e=alertDays(t.item);return`<tr class="alertrow ${null===e?"":daysClass(e)}" style="${t.read?"opacity:.55":""}"><td style="width:20px">${t.read?"":'<span class="dot"></span>'}</td>\n        <td><b>${esc(t.title)}</b><br><span class="muted">${esc(t.body||"")}</span>\n          ${t.item?`<div class="snoozerow">\n            <button class="btn ghost tiny" data-snooze="${esc(t.item)}">Snooze 7 days</button>\n            <button class="btn ghost tiny" data-handled="${esc(t.item)}">Handled</button>\n          </div>`:""}</td>\n        <td class="right muted" style="white-space:nowrap">${new Date(t.created_at+"Z").toLocaleDateString("ro-RO")}</td></tr>`}).join("")}\n      </tbody></table>`:'<div class="empty"><b>No alerts yet</b>They appear here as your bills and deadlines get close.</div>'}\n    </div>`,t.querySelectorAll("[data-snooze],[data-handled]").forEach(e=>e.addEventListener("click",async()=>{const s=e.hasAttribute("data-handled"),a=e.getAttribute(s?"data-handled":"data-snooze");e.disabled=!0;try{await api("/notifications/snooze",{method:"POST",body:s?{item:a,dismiss:!0}:{item:a,days:7}}),toast(s?"Alert hidden — it comes back if the deadline is renewed":"Hidden for 7 days","ok"),viewAlerts(t),pollNotifications()}catch(t){e.disabled=!1,toast(t.message,"err")}})),$("#readall")?.addEventListener("click",async()=>{await api("/notifications/read",{method:"POST",body:{}}),viewAlerts(t),pollNotifications()}),n&&setupPushCard().catch(()=>{}),$("#togglenotif")?.addEventListener("click",async()=>{if(a)localStorage.setItem("fh_notif","0");else{if("granted"!==await Notification.requestPermission())return toast("Permission was not granted");localStorage.setItem("fh_notif","1"),new Notification("Family Hub",{body:"Browser notifications are on."})}viewAlerts(t)})}